import { expect, test } from 'bun:test';
import { createHash } from 'node:crypto';
import { copyFile, mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const prefix = 'packages/herdr-upstream/';
const directory = join(root, prefix);
// Generated by the unchanged native schema generator; the herdr-native CI job
// executes its generator-currentness test against the actual guarded crate.
const generatedSchema = 'docs/next/api/herdr-api.schema.json';

test('Herdr exclusions preserve upstream bytes and one native-generated schema', async () => {
  const { ignore } = await Bun.file(join(root, '.jscpd.json')).json() as { ignore: string[] };
  expect(ignore.filter(pattern => pattern === prefix + generatedSchema)).toHaveLength(1);
  const scopes = ignore.map(pattern => new Bun.Glob(pattern));
  const excluded = (path: string) => scopes.some(scope => scope.match(prefix + path));
  const original = await Bun.file(join(directory, 'SOURCE-MANIFEST.sha256')).text();
  expect(createHash('sha256').update(original).digest('hex')).toBe('1aedd80ed6f09c8421df38bcdac64ec07a089e8f54350f4b198f221d282231a9');
  const manifest = new Map(original.trimEnd().split('\n').map(line => {
    const match = /^([0-9a-f]{64})  (.+)$/.exec(line);
    if (!match || match[2].startsWith('/') || match[2].split('/').includes('..')) throw new Error('Invalid Herdr source manifest');
    return [match[2], match[1]];
  }));
  expect(scopes.some(scope => scope.match('tests/herdr-source.test.ts'))).toBe(false);
  expect(scopes.some(scope => scope.match('packages/herdr-guard/source.rs'))).toBe(false);
  for await (const path of new Bun.Glob('**/*').scan({ cwd: join(root, 'packages/herdr-guard'), onlyFiles: true, dot: true })) {
    expect(scopes.some(scope => scope.match('packages/herdr-guard/' + path)), `Excluded owned guard file: ${path}`).toBe(false);
  }
  expect(excluded('PROVENANCE.md')).toBe(false);
  expect(excluded('SOURCE-MANIFEST.sha256')).toBe(false);
  const checked = new Set<string>();
  for await (const path of new Bun.Glob('**/*').scan({ cwd: directory, onlyFiles: true, dot: true })) {
    if (!excluded(path)) continue;
    expect(manifest.has(path), `Excluded non-upstream file: ${path}`).toBe(true);
    if (path === generatedSchema) {
      expect(await Bun.file(join(directory, path)).exists()).toBe(true);
      checked.add(path);
      continue;
    }
    const bytes = await Bun.file(join(directory, path)).arrayBuffer();
    expect(createHash('sha256').update(new Uint8Array(bytes)).digest('hex'), `Modified excluded upstream file: ${path}`).toBe(manifest.get(path));
    checked.add(path);
  }
  for (const path of manifest.keys()) if (excluded(path)) expect(checked.has(path), `Missing excluded upstream file: ${path}`).toBe(true);
  expect(checked.size).toBeGreaterThan(1000);
});

// Opted in by herdr-native after its checksum-verified Zig and archive provision.
// Execute the exact Actions admission body with real gzip/Zig, without network.
for (const variant of ['matching hash', 'wrong hash', 'truncated archive'] as const) {
  test.skipIf(process.env.LAZYSH_HERDR_UUCODE_FIXTURES !== '1')(`local uucode admission: ${variant}`, async () => {
    const workflow = Bun.YAML.parse(await Bun.file(join(root, '.github/workflows/checks.yml')).text()) as {
      jobs: { 'herdr-native': { steps: { id?: string; run?: string; env?: Record<string, string> }[] } };
    };
    const admission = workflow.jobs['herdr-native'].steps.find(step => step.id === 'uucode-admission')!;
    expect(admission.run).toBeDefined();
    const expected = admission.env!.HERDR_UUCODE_HASH;
    const manifest = await Bun.file(join(directory, 'vendor/libghostty-vt/build.zig.zon')).text();
    expect(manifest).toContain(`.hash = "${expected}"`);
    const fixture = await mkdtemp(join(tmpdir(), 'lazysh-uucode-admission-'));
    try {
      const archive = join(fixture, 'uucode.tar.gz');
      for (const path of ['build.zig', 'build.zig.zon']) {
        await copyFile(join(directory, 'vendor/libghostty-vt', path), join(fixture, path));
      }
      const original = Buffer.from(await Bun.file(process.env.HERDR_UUCODE_ARCHIVE!).arrayBuffer());
      expect(original.length).toBeLessThanOrEqual(33554432);
      await writeFile(archive, variant === 'truncated archive' ? original.subarray(0, 32) : original);
      const child = Bun.spawn(['bash', '-e', '-c', admission.run!], { cwd: fixture,
        env: { ...process.env, HERDR_UUCODE_ARCHIVE: archive,
          HERDR_UUCODE_HASH: variant === 'wrong hash' ? expected + '-wrong' : expected,
          ZIG_GLOBAL_CACHE_DIR: join(fixture, 'global'), ZIG_LOCAL_CACHE_DIR: join(fixture, 'local') },
        stdout: 'pipe', stderr: 'pipe' });
      const [exit, stdout, stderr] = await Promise.all([
        child.exited, new Response(child.stdout).text(), new Response(child.stderr).text(),
      ]);
      expect(exit).toBe(variant === 'matching hash' ? 0 : 1);
      expect(stdout).toBe('');
      if (variant === 'matching hash') expect(stderr).toBe('');
      else expect(stderr).toContain(variant === 'wrong hash' ? 'uucode package hash mismatch' : 'unexpected end of file');
      expect(await Bun.file(join(fixture, 'zig-pkg', expected, 'build.zig.zon')).exists()).toBe(variant !== 'truncated archive');
    } finally {
      await rm(fixture, { recursive: true, force: true });
    }
  }, 100_000);
}
